import{_ as n,a as t,c as o,ac as a}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 单元 5 语法总结","description":"L33–L40 规则、例句、易错点。","frontmatter":{"title":"第四册：流利英语 · 单元 5 语法总结","description":"L33–L40 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L33–L40 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 5：范围、变化与公共论证","link":"/life/english/new-concept/book-4/unit-05/overview"},"next":{"text":"第四册：流利英语 · 单元 5 单词与短语","link":"/life/english/new-concept/book-4/unit-05/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 5：范围、变化与公共论证","link":"/life/english/new-concept/book-4/unit-05/overview"},"next":{"text":"第四册：流利英语 · 单元 5 单词与短语","link":"/life/english/new-concept/book-4/unit-05/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/grammar.md","filePath":"life/english/new-concept/book-4/unit-05/grammar.md"}'),r={name:"life/english/new-concept/book-4/unit-05/grammar.md"};function i(s,e,l,h,p,c){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="第四册-流利英语-·-单元-5-语法总结" tabindex="-1">第四册：流利英语 · 单元 5 语法总结 <a class="header-anchor" href="#第四册-流利英语-·-单元-5-语法总结" aria-label="Permalink to &quot;第四册：流利英语 · 单元 5 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元复习与自测</a></p><h2 id="平行结构与-not-only-but-also" tabindex="-1">平行结构与 not only…but also <a class="header-anchor" href="#平行结构与-not-only-but-also" aria-label="Permalink to &quot;平行结构与 not only…but also&quot;">​</a></h2><p>由 and、or、not only…but also 连接的成分应在语法层级上平行，例如 to question, to compare and to explain，不能混成 to question, comparing and an explanation。not only 放句首引出完整分句时，该分句要部分倒装；放在谓语内部连接宾语时一般不倒装。平行不只关乎词形，也要求项目处于同一逻辑类别，避免把学习行为与资源条件无说明地混列。</p><p><strong>L33 原创例句：</strong> The course teaches students to question claims, compare sources and explain their conclusions.</p><p>这门课程教学生质疑主张、比较来源并解释结论。</p><p><strong>易错：</strong> to question claims, comparing sources and explanations 不平行；应统一为三个动词短语。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-033">Lesson 33</a></p><h2 id="倾向表达与概率范围" tabindex="-1">倾向表达与概率范围 <a class="header-anchor" href="#倾向表达与概率范围" aria-label="Permalink to &quot;倾向表达与概率范围&quot;">​</a></h2><p>tend to do 描述常见倾向，不表示每次或所有人都如此；be likely to do 表示某情况发生的可能性较大，但不是必然。may 与 might 也能降低确定程度。Young people tend to seek… 仍是群体概括，应说明语境或证据来源。避免 tend to always 这类常常相互抵触的范围搭配；若只观察到某个学生，应保留单数对象而不要扩展成整个年龄群体。</p><p><strong>L34 原创例句：</strong> In this club, new members tend to ask their peers for help before approaching an adult.</p><p>在这个俱乐部里，新成员往往先向同伴求助，再找成年人。</p><p><strong>易错：</strong> tend to 不等于 always；不能将示例改写成“所有青少年都只向同伴求助”。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-034">Lesson 34</a></p><h2 id="将来完成时与未来截止点" tabindex="-1">将来完成时与未来截止点 <a class="header-anchor" href="#将来完成时与未来截止点" aria-label="Permalink to &quot;将来完成时与未来截止点&quot;">​</a></h2><p>will have done 表示到某个未来时间点为止预计已经完成的动作，常与 by Friday、by the time…搭配。它不同于 will be doing，后者表示届时正在进行。by the time 引导未来时间从句时通常用一般现在时。计划文本中的 will have completed 是预测或承诺，并不是完成事实；若条件尚不确定，可用 may have completed 或明确加入 if 从句。</p><p><strong>L35 原创例句：</strong> By the time the simulated crew arrives, the support team will have checked every system.</p><p>到模拟机组到达时，支援团队将已检查完所有系统。</p><p><strong>易错：</strong> by the time the crew will arrive 不用于普通未来时间从句；应使用 arrives。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-035">Lesson 35</a></p><h2 id="倍数比较与百分比基数" tabindex="-1">倍数比较与百分比基数 <a class="header-anchor" href="#倍数比较与百分比基数" aria-label="Permalink to &quot;倍数比较与百分比基数&quot;">​</a></h2><p>twice as much as 比较不可数数量，twice as many as 比较可数名词；three times the cost of… 也可表达倍数。increase by 20% 表增加幅度，increase to 20% 表达到的水平，两者不能互换。占比从 20% 到 30% 是增加 10 个百分点，相对原占比增加 50%。使用百分比必须给基数或可恢复的语境，否则读者可能把预算份额与绝对金额混淆。</p><p><strong>L36 原创例句：</strong> In the fictional budget, maintenance costs rose from 100 units to 120 units, an increase of 20%.</p><p>在虚构预算中，维护费从100单位升至120单位，增幅为20%。</p><p><strong>易错：</strong> rose by 120 units 不等于 rose to 120 units；本例只增加20单位。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-036">Lesson 36</a></p><h2 id="比较级重复与渐变表达" tabindex="-1">比较级重复与渐变表达 <a class="header-anchor" href="#比较级重复与渐变表达" aria-label="Permalink to &quot;比较级重复与渐变表达&quot;">​</a></h2><p>形容词比较级 + and + 比较级表示越来越，如 slower and slower；多音节形容词用 more and more complex，不写 more complex and complex。increasingly + 形容词可作较紧凑表达。该结构只给出变化方向，不给变化速度、起点或适用范围。讨论群体研究时应补充 in this sample、over five years 等限定；趋势不意味着所有个体同步变化。</p><p><strong>L37 原创例句：</strong> The records became more and more detailed over the course of the study.</p><p>研究过程中，记录变得越来越详细。</p><p><strong>易错：</strong> more and more better 不成立；better 已是比较级，应写 better and better。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-037">Lesson 37</a></p><h2 id="if、when-后的省略结构" tabindex="-1">if、when 后的省略结构 <a class="header-anchor" href="#if、when-后的省略结构" aria-label="Permalink to &quot;if、when 后的省略结构&quot;">​</a></h2><p>if necessary、when available、if properly stored 等是条件或时间从句的压缩形式。if properly labelled 通常可展开为 if it is properly labelled，但被省略的主语必须能从主句或语境恢复。若前后主语不同，省略可能造成歧义。When travelling, check… 中 travelling 的执行者是祈使句隐含的 you；不能把同一短语接到 water is… 前，造成水在旅行的错误。</p><p><strong>L38 原创例句：</strong> When travelling, check current local guidance rather than rely on an old account.</p><p>旅行时，应核查当前当地指导信息，而不是依赖一篇旧记述。</p><p><strong>易错：</strong> When travelling, the water… 容易把 travelling 的执行者错接成 water；应明确人作主语。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-038">Lesson 38</a></p><h2 id="wish-后的时态与非现实意义" tabindex="-1">wish 后的时态与非现实意义 <a class="header-anchor" href="#wish-后的时态与非现实意义" aria-label="Permalink to &quot;wish 后的时态与非现实意义&quot;">​</a></h2><p>wish + 一般过去时常表示对现在不满意而希望不同，如 I wish the ending were clearer。wish + had done 表示对过去的遗憾；wish + would do 常表达希望某人或某事改变，不能随意替代自己的可控计划。be 在较正式非现实表达中常用 were。希望未来有可能实现的结果通常用 hope；I hope readers will respond 与 I wish readers responded 的现实距离不同。</p><p><strong>L39 原创例句：</strong> I wish the opening were shorter, because the main point arrives too late.</p><p>我希望开头短一些，因为重点出现得太晚。</p><p><strong>易错：</strong> 不要把对现有稿件的遗憾写成 wish the opening is shorter；此处需要过去形式表达非现实。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-039">Lesson 39</a></p><h2 id="where-的地点与条件意义" tabindex="-1">where 的地点与条件意义 <a class="header-anchor" href="#where-的地点与条件意义" aria-label="Permalink to &quot;where 的地点与条件意义&quot;">​</a></h2><p>where 可以引导地点从句，也可在正式论述中表示“在……情况下”。Where the surface is uneven, the pattern becomes harder to interpret. 既可指表面不平的区域，也可泛指这种条件；语境决定侧重点。不能把 where 任意代替 when：时间应优先用 when，明确假设可用 if。关系从句中的 where 相当于 in/at which，只有先行词和介词关系合理时才可转换。</p><p><strong>L40 原创例句：</strong> Where the water meets the barrier, the pattern changes.</p><p>在水与障碍物相接的地方，波纹形态发生变化。</p><p><strong>易错：</strong> 不要把“实验结束时”写成 where the experiment ends；普通时间关系应写 when the experiment ends。</p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-040">Lesson 40</a></p>',50)])])}const u=n(r,[["render",i]]);export{g as __pageData,u as default};
